section.sourcecode:
Rx = 0              # 現在の送信レート（テーブルの行に相当）

seqErr = 0          # 損失、順序の入れ替わり、重複の障害（いずれも
                    # 最初はパケットのシーケンス番号のエラーとして
                    # 現れる）を含む測定されたカウント

seqErrThresh = 10   # 損失、順序の入れ替わり、重複の障害（いずれも
                    # 最初はパケットのシーケンス番号のエラーとして
                    # 現れる）を含むseqErrカウントのしきい値

delay = 0           # 測定された往復遅延（RTD）の範囲、ミリ秒

lowThresh = 30      # RTDの範囲の下限しきい値、ミリ秒

upperThresh = 90    # RTDの範囲の上限しきい値、ミリ秒

hSpeedThresh = 1    # 送信レートのステップサイズ（1 Mbpsと100 Mbps
                    # など）を切り替えるしきい値、Gbps

slowAdjCount = 0    # upperThreshを上回る損失や遅延変動を示す、連続
                    # したステータス報告の測定された数

slowAdjThresh = 3   # 輻輳の推定に使用するslowAdjCountのしきい値。
                    # 一時的な損失の誤解釈を避けるため、> 1の値を
                    # 使用する。

highSpeedDelta = 10 # 最初に提供負荷を増加させる際に（すばやく
                    # ランプアップするために）1回の調整で移動する行数

maxLoadRates = 2000 # テーブルの最大インデックス（行）

if ( seqErr <= seqErrThresh && delay < lowThresh ) {
        if ( Rx < hSpeedThresh && slowAdjCount < slowAdjThresh ) {
                        Rx += highSpeedDelta;
                        slowAdjCount = 0;
        } else {
                        if ( Rx < maxLoadRates - 1 )
                                        Rx++;
        }
} else if ( seqErr > seqErrThresh || delay > upperThresh ) {
        slowAdjCount++;
        if ( Rx < hSpeedThresh && slowAdjCount == slowAdjThresh ) {
                        if ( Rx > highSpeedDelta * 3 )
                                        Rx -= highSpeedDelta * 3;
                        else
                                        Rx = 0;
        } else {
                        if ( Rx > 0 )
                                        Rx--;
        }
}
